# If you do not have elDump and netViewX you can get them from
# http://www.ibt.ku.dk/jesper/NTtools
########################################################################
$eldump = "eldump";
$netviewx = "netviewx";


$usage = <<EOT;
Usage: srvboot [\\\\server|domain]... [-S [dir]] [-w] [-a time|-A days]
               [-b time|-B days]

The srvboot command will print the times where one or more NT servers where
booted. If the server was not booted since the System event log was last
cleared, then nothing is printed.

  \\\\server    Print when the server was last booted.
  domain      Print when all NT Servers in the domain was last booted.
              You can specify one or more servers and domains. If no servers
              or domains are specified, srvboot will print when the current
              NT machine was booted.
  -S [dir]    Also look in saved event logs (see the documentation for
              elDump -S).
  -a time     Only print boots after this time [YY]YYMMDD[HH[MM[SS]]].
  -A days     Only print boots in the last specified number of days.
  -b time     Only print boots before this time [YY]YYMMDD[HH[MM[SS]]].
  -B days     Only print boots before the specified number of days.
  -w          Also print boots for NT Workstations in the specified domains.
	
EOT

use Getopt::Long;
Getopt::Long::Configure("no_ignore_case","bundling");
$optresult = GetOptions(
	"S:s",\$opt_Saved,
	"a=s",\$opt_after,
	"A=i",\$opt_Afterdays,
	"b=s",\$opt_before,
	"B=i",\$opt_Beforedays,
	"w",\$opt_workstations,
	"h|?",\$opt_help,
);

if (!$optresult || $opt_help) {
	print $usage;
	exit 1;
}

$after = "";
if ($opt_after) {$after = "-a $opt_after"}
elsif ($opt_Afterdays) {$after = "-A ".($opt_Afterdays*24)}
$before = "";
if ($opt_before) {$before = "-b $opt_before"}
elsif ($opt_Beforedays) {$before = "-B ".($opt_Beforedays*24)}

$type = (($opt_workstations)? "nt" : "server_nt domain_ctrl domain_bakctrl");

if (@ARGV) {
	while (@ARGV) {
		$arg = shift @ARGV;
		if ($arg =~ /^\\\\/) {
			eldump($arg);
		} else {
			foreach (`$netviewx $arg $type -On`) {eldump("\\\\$_")}
		}
	}
} else {
 eldump("");
}


sub eldump {
	my($server) = shift;
	if (defined($opt_Saved)) {$server = "-S a+c $server $opt_Saved"}
	#print "$eldump -mEventLog -e6005 -lsystem -Odto -QYM $after $before $server\n";
